import java.io.*;
import java.util.*;
class Solution {
    public int longestSubarray(long[] nums, long limit) {
        ArrayDeque<Integer> maxD=new ArrayDeque<>(), minD=new ArrayDeque<>();
        int left=0, ans=0;
        for(int right=0; right<nums.length; right++){
            while(!maxD.isEmpty() && nums[maxD.peekLast()]<=nums[right]) maxD.pollLast();
            maxD.addLast(right);
            while(!minD.isEmpty() && nums[minD.peekLast()]>=nums[right]) minD.pollLast();
            minD.addLast(right);
            while(nums[maxD.peekFirst()]-nums[minD.peekFirst()]>limit){
                if(maxD.peekFirst()==left) maxD.pollFirst();
                if(minD.peekFirst()==left) minD.pollFirst();
                left++;
            }
            ans=Math.max(ans,right-left+1);
        }
        return ans;
    }
}

