function longestSubarray(nums, limit){
  const maxD=[], minD=[]; let maxH=0,minH=0,left=0,ans=0;
  for(let right=0;right<nums.length;right++){
    const x=nums[right];
    while(maxD.length>maxH && nums[maxD[maxD.length-1]]<=x) maxD.pop();
    maxD.push(right);
    while(minD.length>minH && nums[minD[minD.length-1]]>=x) minD.pop();
    minD.push(right);
    while(nums[maxD[maxH]]-nums[minD[minH]]>limit){
      if(maxD[maxH]===left) maxH++;
      if(minD[minH]===left) minH++;
      left++;
    }
    ans=Math.max(ans,right-left+1);
  }
  return ans;
}

