 int mh=0,mt=0,nh=0,nt=0,left=0,ans=0;
 for(int r=0;r<n;r++){
  while(mt>mh && a[mx[mt-1]]<=a[r]) --mt;
  mx[mt++]=r;
  while(nt>nh && a[mn[nt-1]]>=a[r]) --nt;
  mn[nt++]=r;
  while(a[mx[mh]]-a[mn[nh]]>limit){
   if(mx[mh]==left) ++mh;
   if(mn[nh]==left) ++nh;
   ++left;
  }
  int len=r-left+1; if(len>ans)ans=len;
 }
 free(mx);free(mn);return ans;
}

